function Invoke-ProSoakOffline($Session,$Guard,[string]$ProNonce,[string]$ScriptDirectory){
 $meta=$Guard.ReadCommand('soak-inputs.json')|ConvertFrom-Json;$reader=$Guard.ReadCommand('volume-reader-inputs.json')|ConvertFrom-Json
 if($meta.caseId -notmatch '^[a-f0-9]{32}$' -or $reader.caseId -notmatch '^[a-f0-9]{32}$' -or $reader.manifestSha256 -notmatch '^[a-f0-9]{64}$' -or $meta.proNonce -ne $ProNonce -or $reader.proNonce -ne $ProNonce){throw 'Bound failed soak and immutable reader reference required'}
 $source=Join-Path $ScriptDirectory 'pro-soak-readonly.py';$Guard.PinInputFile($source);$sha=(Get-FileHash -LiteralPath $source).Hash.ToLowerInvariant();$destination='C:\MuLab\approved\soak-'+$meta.caseId+'-readonly-'+$sha.Substring(0,16)+'.py'
 $unused=Invoke-Command -Session $Session -ArgumentList $meta.caseId,$destination -ScriptBlock {param($caseId,$destination) if(Test-Path -LiteralPath $destination){throw 'Existing forensic work must be inspected'};return $true};if(-not $unused){throw 'Forensic destination unavailable'};Copy-Item -LiteralPath $source -Destination $destination -ToSession $Session
 return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$reader,$sha,$destination -ScriptBlock {
  param($caseId,$reader,$sha,$script)
  $ErrorActionPreference='Stop';$approved='C:\MuLab\approved\soak-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json;$result=[IO.File]::ReadAllText($approved+'-result.json')|ConvertFrom-Json;$id=[string]$result.nested.id;$vm=Get-VM -Id ([guid]$result.nested.platformId)
  if($result.caseId -ne $caseId -or $result.complete -ne $false -or -not $result.processExitConfirmed -or -not $result.brokerExitConfirmed -or -not $result.nested.confirmedOff -or $result.nested.removed -or $vm.Name -ne ('mu-win-'+$id.Replace('-','')) -or $vm.Notes -ne ('MuCodeSandbox Windows preview '+$vm.Name) -or [string]$vm.State -ne 'Off' -or @(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -eq $cfg.node -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe'}).Count){throw 'Exact terminal stopped failed soak required'}
  $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json;$disk=Join-Path $root ('vms/'+$id+'/disk.vhdx');$drives=@(Get-VMHardDiskDrive -VM $vm)
  if($ledger.ownerSid -ne $cfg.userSid -or $ledger.records.$id.ownerSid -ne $cfg.userSid -or $ledger.records.$id.platformId -ne [string]$vm.Id -or $drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne $disk){throw 'Stopped soak disk identity changed'}
  $tools='C:\MuLab\volume-readers\'+$reader.caseId+'-'+$reader.manifestSha256.Substring(0,16);if((Get-FileHash (Join-Path $tools 'manifest.json')).Hash.ToLowerInvariant() -ne $reader.manifestSha256 -or (Get-FileHash $script).Hash.ToLowerInvariant() -ne $sha){throw 'Immutable parser/source changed'};$manifest=[IO.File]::ReadAllText((Join-Path $tools 'manifest.json'))|ConvertFrom-Json;foreach($entry in $manifest.psobject.Properties){if((Get-FileHash (Join-Path $tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Read-only runtime file changed'}}
  $binding=@{caseId=$caseId;userSid=$cfg.userSid;id=$id;disk=$disk;startedAt=$result.startedAt};if(Test-Path ($approved+'-offline.json')){$old=[IO.File]::ReadAllText($approved+'-offline.json')|ConvertFrom-Json;foreach($key in $binding.Keys){if($old.$key -cne $binding[$key]){throw 'Original forensic binding changed'}}}else{[IO.File]::WriteAllText($approved+'-offline.json',($binding|ConvertTo-Json),[Text.UTF8Encoding]::new($false))};$pin=[IO.File]::Open($disk,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
  try{$before=(Get-FileHash $disk).Hash.ToLowerInvariant();$actor=Start-Process -FilePath (Join-Path $tools 'python.exe') -ArgumentList @($script,$caseId,$sha.Substring(0,16)) -WindowStyle Hidden -RedirectStandardOutput ($approved+'-offline-'+$sha.Substring(0,16)+'-out.log') -RedirectStandardError ($approved+'-offline-'+$sha.Substring(0,16)+'-error.log') -PassThru;$null=$actor.Handle;if(-not $actor.WaitForExit(240000)){throw 'Offline parser remains live; preserve the process and original disk'};if($actor.ExitCode -ne 0){throw ('Offline parser failed: '+[IO.File]::ReadAllText($approved+'-offline-'+$sha.Substring(0,16)+'-error.log'))};$after=(Get-FileHash $disk).Hash.ToLowerInvariant();if($after -ne $before){throw 'Offline original disk changed'};return @{complete=$true;caseId=$caseId;readOnly=$true;diskUnchanged=$true;diskSha256=$before;parserSha256=$sha;result=([IO.File]::ReadAllText($approved+'-offline-'+$sha.Substring(0,16)+'.json')|ConvertFrom-Json)}}finally{$pin.Dispose()}
 }
}
